  109 |   const dimsRef = useRef({ w: 0, h: 0, dpr: 1 });
  110 |
> 111 |   playingRef.current = playing;
      |   ^^^^^^^^^^^^^^^^^^ Cannot update ref during render
  112 |   speedRef.current = speed;
  113 |   focusedRef.current = focused;
  114 |

